//! 🎟️ Original source headers retain actual pointer and payload allocations under zero alias-copy authority.
use crate::{RetainedCloneSource,RetainedCloneGrant,RetainedCloneProgress,observe_retirement_allocations};
fn close_original_header_source<A:crate::retirement::RetireOwned+Sync>(mut source:RetainedCloneSource<String,A>,original:*const u8,body:usize,mut born:usize,mut released:usize){
    let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_depth:1,..Default::default()};assert_eq!(source.borrow().binding_copy_bytes(),0);
    for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observe_retirement_allocations(||source.project_owned(0,|value|value.as_str(),denied));assert_eq!(heap,(0,0));assert!(result.is_err());assert_eq!(source.borrow().get().as_ptr(),original);}
    let((mut projection,receipt),heap)=observe_retirement_allocations(||source.project_owned(0,|value|value.as_str(),grant).unwrap());assert_eq!(heap,(0,0));assert_eq!(receipt,RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!(projection.borrow().unwrap().get().as_ptr(),original);
    let mut binding=None;let(progress,heap)=observe_retirement_allocations(||source.borrow().project(5,|value|value.as_str()).bind(&mut binding,grant).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(progress,RetainedCloneProgress{copied_items:1,..Default::default()});
    let(refused,heap)=observe_retirement_allocations(||source.borrow().project(6,|value|value.as_str()).bind(&mut binding,grant));assert_eq!(heap,(0,0));assert!(refused.is_err());assert_eq!(source.borrow().get().as_ptr(),original);
    for _ in 0..10000{if binding.is_none(){break;}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:crate::RetainedCloneBinding::capacity_demand(&binding,body).unwrap(),maximum_release_bytes:crate::RetainedCloneBinding::release_demand(&binding).unwrap(),maximum_depth:crate::RetainedCloneBinding::depth_demand(&binding).unwrap()};let(step,heap)=observe_retirement_allocations(||crate::RetainedCloneBinding::close_one(&mut binding,grant).unwrap());let receipt=step.progress();assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;released+=heap.1;assert!(receipt.copied_items!=0);}assert!(binding.is_none());
    let((mut child,receipt),heap)=observe_retirement_allocations(||projection.project(2,|value|value,grant).unwrap());assert_eq!(heap,(0,0));assert_eq!(receipt,RetainedCloneProgress{copied_items:1,..Default::default()});assert_eq!(child.borrow().unwrap().get().as_ptr(),original);
    for alias in [&mut child,&mut projection]{for _ in 0..10000{if alias.terminal_is_empty(){break;}let(demand,heap)=observe_retirement_allocations(||alias.next_close_demand(body).unwrap());assert_eq!(heap,(0,0));let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,heap)=observe_retirement_allocations(||alias.close_step(grant).unwrap());let receipt=step.progress();assert!(receipt.fits(grant));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;released+=heap.1;assert!(receipt.copied_items!=0);}assert!(alias.terminal_is_empty());assert_eq!(source.borrow().get().as_ptr(),original);}
    assert_eq!(observe_retirement_allocations(||drop(child)).1,(0,0));assert_eq!(observe_retirement_allocations(||drop(projection)).1,(0,0));
    for _ in 0..10000{if source.terminal_is_empty(){break;}let(demand,heap)=observe_retirement_allocations(||source.next_close_demand(body).unwrap());assert_eq!(heap,(0,0));let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,heap)=observe_retirement_allocations(||source.close_step(grant).unwrap());let receipt=step.progress();assert!(receipt.fits(grant));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));born+=heap.0;released+=heap.1;assert!(receipt.copied_items!=0,"original source header close stalled at literal body");}
    assert!(source.terminal_is_empty());assert_eq!(observe_retirement_allocations(||drop(source)).1,(0,0));assert_eq!(born,released);
}

#[test]
fn original_owned_and_borrowed_source_headers_preserve_pointer_and_actual_capacity(){
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎟️header.json")).unwrap();
    for body in law["cancelBodies"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;
        let((owner,authority),factory)=observe_retirement_allocations(||(law["owner"].as_str().unwrap().to_owned(),law["authority"].as_str().unwrap().to_owned()));let original=owner.as_ptr();let demand=RetainedCloneSource::<String>::owned_constructor_demand::<String>();assert_eq!(RetainedCloneSource::<String>::constructor_copy_bytes(),0);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:demand.capacity_bytes,maximum_depth:demand.depth,..Default::default()};
        let((source,receipt),heap)=observe_retirement_allocations(||RetainedCloneSource::admit_owned(owner,authority,grant).map_err(|(error,_,_)|error).unwrap());assert_eq!(heap,(demand.capacity_bytes,0));assert_eq!(receipt,RetainedCloneProgress{copied_items:1,retained_capacity_bytes:demand.capacity_bytes,..Default::default()});close_original_header_source(source,original,body,factory.0+heap.0,factory.1+heap.1);
        let((mut owner,mut authority),factory)=observe_retirement_allocations(||(law["owner"].as_str().unwrap().to_owned(),law["authority"].as_str().unwrap().to_owned()));let pointers=(owner.as_ptr(),authority.as_ptr());let demand=RetainedCloneSource::<String>::borrowed_constructor_demand::<(String,String)>();assert_eq!(RetainedCloneSource::<String>::borrowed_constructor_copy_bytes::<(String,String)>(),0);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:demand.capacity_bytes,maximum_depth:demand.depth,..Default::default()};
        for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observe_retirement_allocations(||RetainedCloneSource::<String>::admit_borrowed((owner,authority),|value|&value.0,denied));assert_eq!(heap,(0,0));let(_,original)=result.err().expect("original borrowed source denial");owner=original.0;authority=original.1;assert_eq!((owner.as_ptr(),authority.as_ptr()),pointers);}
        let((source,receipt),heap)=observe_retirement_allocations(||RetainedCloneSource::<String>::admit_borrowed((owner,authority),|value|&value.0,grant).map_err(|(error,_)|error).unwrap());assert_eq!(heap,(demand.capacity_bytes,0));assert_eq!(receipt,RetainedCloneProgress{copied_items:1,retained_capacity_bytes:demand.capacity_bytes,..Default::default()});close_original_header_source(source,pointers.0,body,factory.0+heap.0,factory.1+heap.1);
    }
}

